const fmtDate = (iso) =>
  new Date(iso).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
const titleCase = (key) => {
  const words = key.replace(/([A-Z])/g, " $1").toLowerCase();
  return words[0].toUpperCase() + words.slice(1);
};

async function getJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${res.status} on ${url}`);
  return res.json();
}

function renderMeta(recs, aaData, pricing) {
  const generatedAt = new Date(recs.generatedAt);
  const staleBadge = (fetchedAt) =>
    generatedAt - new Date(fetchedAt) > STALE_MS ? '<span class="badge">stale</span>' : "";
  const source = (name, url, fetchedAt, note = "", lead = false) =>
    `<li${lead ? ' class="lead"' : ""}><span><a href="${esc(url)}">${esc(name)}</a>${note}</span>` +
    (fetchedAt
      ? `<span><time datetime="${esc(fetchedAt)}">${esc(fmtDate(fetchedAt))}</time>${staleBadge(fetchedAt)}</span>`
      : "<span>unavailable</span>") +
    "</li>";
  const aaVersion =
    aaData?.intelligenceIndexVersion != null
      ? ` <span class="note">Intelligence Index v${esc(aaData.intelligenceIndexVersion)}</span>`
      : "";
  const items = [
    source(
      "Artificial Analysis",
      "https://artificialanalysis.ai/",
      aaData?.fetchedAt,
      aaVersion,
      true,
    ),
    ...PROVIDERS.map((p, i) => source(p.name, p.docs, pricing[i]?.fetchedAt)),
  ];
  document.getElementById("updated").innerHTML =
    `Menu updated <time datetime="${esc(recs.generatedAt)}">${esc(fmtDate(recs.generatedAt))}</time>` +
    ` · ${num(recs.candidatesConsidered, 0)} models scored · data as of:`;
  document.getElementById("sources").innerHTML = items.join("");
}

const displayName = (r) => (r.effort ? `${r.model} (${r.effort})` : r.model);

function renderTable(rows) {
  if (!rows?.length) return '<p class="empty">Ze cupboard is bare: no scored models.</p>';
  const body = rows
    .map(
      (r, i) => `<tr${i === 0 ? ' class="top"' : ""}>
        <td>${i + 1}</td>
        <td class="model"><span class="name" title="${esc(displayName(r))}">${esc(displayName(r))}</span></td>
        <td class="score">${num(r.score)}</td>
        <td>${num(r.breakdown.quality)}</td>
        <td>$${num(r.breakdown.costPerTask, 3)}</td>
        <td>${num(r.breakdown.responseTimeSeconds, 0)} s</td>
        <td>$${num(r.priceBlendedPer1M, 3)}</td>
      </tr>`,
    )
    .join("");
  return `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>Model</th><th>Score</th>
      <th title="This category's mix of Artificial Analysis indexes, in index points">Quality</th>
      <th title="Estimated cost of one Intelligence Index task at this provider's prices">$/task</th>
      <th title="Seconds until a 500-token answer is complete, thinking included">Time</th>
      <th>$/1M</th>
    </tr></thead>
    <tbody>${body}</tbody>
  </table></div>`;
}

function renderCategory(name, byProvider, config) {
  const mix = Object.entries(config?.quality ?? {})
    .filter(([, w]) => w > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([k, w]) => `<li>${esc(QUALITY_LABELS[k] ?? k)} ${Math.round(w * 100)}%</li>`);
  const rates = [
    ["pointsPerCostDoubling", "cost"],
    ["pointsPerTimeDoubling", "time"],
  ]
    .filter(([key]) => config?.[key] != null)
    .map(([key, label]) => `<li>−${num(config[key])} per doubling of ${label}</li>`);
  const weights = [...mix, ...rates].join("");
  const providers = PROVIDERS.map(
    (p) =>
      `<div><h3><span class="chez">chez</span> ${p.name}</h3>${renderTable(byProvider[p.id])}</div>`,
  ).join("");
  return `<section class="category">

